css:
@keyframes ping {
  to {
    opacity: 0;
    transform: scale(2.5);
  }
}

.bar {
  padding: 40px;
  font-family: system-ui, sans-serif;
}

.bell {
  position: relative;
  padding: 10px 18px;
  border: 1px solid #e4e4e7;
  border-radius: 8px;
  background-color: #ffffff;
  font: inherit;
}

.dot {
  position: absolute;
  top: -4px;
  right: -4px;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: #ef4444;
}

.dot::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background-color: #ef4444;
  animation: ping 1.2s ease-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  .dot::after {
    animation: none;
  }
}
